import { getModalSurface } from '../../utils/modalSurface';
import React, { useState, useEffect, useMemo, useCallback } from 'react';
import Joyride, { CallBackProps, Step, STATUS } from 'react-joyride';
import Cookies from 'js-cookie';
import { User } from 'firebase/auth';
import { useTheme } from '@mui/material/styles';
import Box from '@mui/material/Box';
import Paper from '@mui/material/Paper';
import Typography from '@mui/material/Typography';
import Button from '@mui/material/Button';
import { useTranslation } from '../../hooks/useTranslation';

interface DashboardTourProps {
  user: User | null;
  wpToken: string | null;
}

const DashboardTour: React.FC<DashboardTourProps> = ({ user, wpToken: _wpToken }) => {
  const theme = useTheme();
  const surface = getModalSurface(theme.palette.mode);
  const { t } = useTranslation();
  const [run, setRun] = useState(false);
  const [tourStarted, setTourStarted] = useState(false);
  const [showTourPrompt, setShowTourPrompt] = useState(false);

  const steps = useMemo<Step[]>(
    () => [
      {
        target: '.verse__selected .verse__text',
        content: String(t('tour.selectVerse.content')),
        disableBeacon: true,
        placement: 'top',
        title: String(t('tour.selectVerse.title')),
      },
    ],
    [t],
  );

  const getStorageKeys = useCallback(() => {
    if (user?.uid) {
      return {
        completedCookie: `dashboardTourCompleted_${user.uid}`,
        completedLocal: `dashboardTourCompleted_${user.uid}`,
        declinedLocal: `dashboardTourPromptDeclined_${user.uid}`,
      };
    }
    return {
      completedCookie: 'dashboardTourCompleted',
      completedLocal: 'dashboardTourCompleted',
      declinedLocal: 'dashboardTourPromptDeclined',
    };
  }, [user]);

  const hasCompletedTour = useCallback(() => {
    const keys = getStorageKeys();
    return (
      Cookies.get(keys.completedCookie) === 'true' ||
      localStorage.getItem(keys.completedLocal) === 'true'
    );
  }, [getStorageKeys]);

  const hasDeclinedPrompt = useCallback(() => {
    const keys = getStorageKeys();
    return localStorage.getItem(keys.declinedLocal) === 'true';
  }, [getStorageKeys]);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const resetTour = urlParams.get('resetTour');

    if (resetTour === 'true') {
      const keys = getStorageKeys();
      Cookies.remove(keys.completedCookie, { path: '/' });
      localStorage.removeItem(keys.completedLocal);
      localStorage.removeItem(keys.declinedLocal);
      setShowTourPrompt(true);
      return;
    }

    if (hasCompletedTour() || hasDeclinedPrompt()) {
      setShowTourPrompt(false);
      return;
    }

    setShowTourPrompt(true);
  }, [user, getStorageKeys, hasCompletedTour, hasDeclinedPrompt]);

  const startTour = useCallback(() => {
    setShowTourPrompt(false);
    const event = new CustomEvent('tourStarted', {
      detail: { selectVerse: true },
    });
    window.dispatchEvent(event);
    setTimeout(() => setRun(true), 500);
  }, []);

  const handleTourPromptCancel = useCallback(() => {
    setShowTourPrompt(false);
    const keys = getStorageKeys();
    localStorage.setItem(keys.declinedLocal, 'true');
  }, [getStorageKeys]);

  const handleJoyrideCallback = (data: CallBackProps) => {
    const { status, type } = data;
    const finishedStatuses: string[] = [STATUS.FINISHED, STATUS.SKIPPED];

    if (type === 'tour:start' || type === 'step:after') {
      setTourStarted(true);
      if (type === 'tour:start') {
        const event = new CustomEvent('tourStarted', {
          detail: { selectVerse: true },
        });
        window.dispatchEvent(event);
      }
    }

    if (finishedStatuses.includes(status) && tourStarted) {
      setRun(false);
      const keys = getStorageKeys();
      Cookies.set(keys.completedCookie, 'true', { expires: 365, path: '/' });
      localStorage.setItem(keys.completedLocal, 'true');
    } else if (finishedStatuses.includes(status) && !tourStarted) {
      setRun(false);
    }
  };

  return (
    <>
      {showTourPrompt && (
        <Paper
          elevation={6}
          sx={{
            position: 'fixed',
            bottom: 12,
            right: 12,
            zIndex: 10040,
            px: 1.25,
            py: 1,
            maxWidth: 200,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'stretch',
            gap: 0.75,
            ...surface,
          }}
        >
          <Typography
            variant="body2"
            component="p"
            sx={{
              fontWeight: 600,
              fontSize: '0.8125rem',
              lineHeight: 1.3,
              textAlign: 'center',
              color: 'text.primary',
            }}
          >
            {String(t('tour.prompt.title'))}
          </Typography>
          <Box sx={{ display: 'flex', justifyContent: 'center', gap: 0.75 }}>
            <Button
              size="small"
              variant="contained"
              color="primary"
              onClick={startTour}
              sx={{ minWidth: 56, py: 0.25, fontSize: '0.75rem' }}
            >
              {String(t('tour.prompt.ok'))}
            </Button>
            <Button
              size="small"
              variant="text"
              color="inherit"
              onClick={handleTourPromptCancel}
              sx={{ minWidth: 56, py: 0.25, fontSize: '0.75rem' }}
            >
              {String(t('tour.prompt.cancel'))}
            </Button>
          </Box>
        </Paper>
      )}

      <Joyride
        callback={handleJoyrideCallback}
        continuous={false}
        hideCloseButton
        run={run}
        scrollToFirstStep
        showProgress={false}
        showSkipButton
        locale={{
          last: String(t('tour.buttons.complete')),
          next: String(t('tour.buttons.next')),
          skip: String(t('tour.buttons.skip')),
          back: String(t('tour.buttons.back')),
        }}
        steps={steps}
        styles={{
          options: {
            backgroundColor: surface.backgroundColor,
            primaryColor: theme.palette.primary.main,
            textColor: theme.palette.text.primary,
            arrowColor: surface.backgroundColor,
            zIndex: 10050,
          },
          tooltip: {
            ...surface,
            fontSize: '14px',
          },
          tooltipFooter: {
            marginTop: '14px',
          },
          spotlight: {
            backgroundColor: 'rgba(0, 0, 0, 0.4)',
          },
          tooltipContainer: {
            textAlign: 'left',
          },
          tooltipTitle: {
            fontSize: '16px',
            fontWeight: 'bold',
            marginLeft: '0.5rem',
            color: theme.palette.primary.main,
          },
          buttonNext: {
            backgroundColor: theme.palette.mode === 'light' ? '#ffffff' : '#212121',
            color: theme.palette.mode === 'dark' ? '#ffffff' : '#212121',
          },
          buttonBack: {
            color: '#A1A1A1',
          },
          buttonSkip: {
            color: theme.palette.text.secondary,
          },
        }}
      />
    </>
  );
};

export default DashboardTour;
