/** Reviewed content correspondences; see docs/verse-identity-evidence.md. */
export interface VerseReference {
  book: string;
  chapter: number;
  verse: number;
}

export interface SourceVerseReference extends Omit<VerseReference, 'verse'> {
  verse: string | number;
}

export interface ContentSpan {
  translation: string;
  source: readonly [SourceVerseReference, ...SourceVerseReference[]];
  kjv: readonly [VerseReference, ...VerseReference[]];
  reason: string;
}

const ref = (book: string, chapter: number, verse: number): VerseReference => ({
  book,
  chapter,
  verse,
});

