export const sameReference = (a: SourceVerseReference, b: SourceVerseReference): boolean =>
  a.book.toLowerCase().trim().replace(/\s+/g, '') ===
    b.book.toLowerCase().trim().replace(/\s+/g, '') &&
  Number(a.chapter) === Number(b.chapter) &&
  String(a.verse).trim() === String(b.verse).trim();
