import { interfaceText } from '../../../i18n/interfaceText';
import useHighlight from '../../../hooks/useHighlight';
import React from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  FormControlLabel,
  Checkbox,
  Typography,
  Box,
} from '@mui/material';
import Cookies from 'js-cookie';

import { useTranslation } from '../../../hooks/useTranslation';

interface SignOutDialogProps {
  open: boolean;
  onClose: () => void;
  onConfirm: () => void;
}

export default function SignOutDialog({ open, onClose, onConfirm }: SignOutDialogProps) {
  const { t } = useTranslation();
  const { clearLocalCache } = useHighlight();
  const [saveHighlightedVerses, setSaveHighlightedVerses] = React.useState(true);
  const [saveBookmark, setSaveBookmark] = React.useState(true);
  const [saveSession, setSaveSession] = React.useState(true);

  const handleSignOut = () => {
    if (!saveSession) {
      // Clear session cookies if not saving
      Cookies.remove('wpToken');
      Cookies.remove('userId');
    }

    if (!saveHighlightedVerses) {
      // Clear highlighted verses cookie
      clearLocalCache();
      // Account highlights remain on WordPress. Preserve the unowned legacy
      // cookie for explicit review/import; signing out must not destroy it.
    }

    if (!saveBookmark) {
      // Clear bookmark cookie
      Cookies.remove('bookmark');
    }

    document.cookie.split(';').forEach((c) => {
      const cookieName = c.split('=')[0].replace(/^ +/, '');
      if (cookieName === 'highlightedVerses') {
        return;
      }
      document.cookie = cookieName + '=;expires=' + new Date(0).toUTCString() + ';path=/';
    });

    onConfirm();
  };

  return (
    <Dialog open={open} onClose={onClose}>
      <DialogTitle
        sx={{
          fontFamily: 'Helvetica, Arial, sans-serif',
          fontWeight: 800,
          letterSpacing: '1.15px',
        }}
      >
        {String(t('signOutDialog.title'))}
      </DialogTitle>
      <DialogTitle
        sx={{
          mt: -1,
          fontWeight: 200,
        }}
      >
        {String(t('signOutDialog.subtitle'))}
      </DialogTitle>
      <DialogContent>
        <Box sx={{ mb: 2 }}>
          <FormControlLabel
            control={
              <Checkbox
                checked={saveHighlightedVerses}
                onChange={(e) => setSaveHighlightedVerses(e.target.checked)}
                sx={{
                  color: '#a1a1a1',
                  '&.Mui-checked': {
                    color: '#a1a1a1',
                  },
                }}
              />
            }
            label={
              <>
                <span>{String(t('signOutDialog.saveHighlightedVerses'))}</span>
                <Typography sx={{ fontSize: 11, color: 'text.secondary' }}>
                  {interfaceText('Keep a local copy. Account highlights stay saved either way.')}
                </Typography>
              </>
            }
          />
          <FormControlLabel
            control={
              <Checkbox
                checked={saveBookmark}
                onChange={(e) => setSaveBookmark(e.target.checked)}
                sx={{
                  color: '#a1a1a1',
                  '&.Mui-checked': {
                    color: '#a1a1a1',
                  },
                }}
              />
            }
            label={String(t('signOutDialog.saveBookmark'))}
          />
          <FormControlLabel
            control={
              <Checkbox
                checked={saveSession}
                onChange={(e) => setSaveSession(e.target.checked)}
                sx={{
                  color: '#a1a1a1',
                  '&.Mui-checked': {
                    color: '#a1a1a1',
                  },
                }}
              />
            }
            label={String(t('signOutDialog.saveSession'))}
          />
        </Box>
        <Typography variant="body2" sx={{ color: '#a1a1a1', fontSize: '14px' }}>
          {String(t('signOutDialog.sessionNote'))}
        </Typography>
      </DialogContent>
      <DialogActions sx={{ p: 2 }}>
        <Button
          onClick={onClose}
          variant="outlined"
          sx={{
            color: (theme) => (theme.palette.mode === 'light' ? '#212121' : '#a1a1a1'),
            borderColor: (theme) => (theme.palette.mode === 'light' ? '#212121' : '#a1a1a1'),
            '&:hover': {
              backgroundColor: (theme) => (theme.palette.mode === 'light' ? '#212121' : '#FFF'),
              borderColor: (theme) => (theme.palette.mode === 'light' ? '#212121' : '#FFF'),
            },
          }}
        >
          {String(t('common.cancel'))}
        </Button>
        <Button
          onClick={handleSignOut}
          variant="contained"
          sx={{
            backgroundColor: '#a1a1a1',
            color: '#FFF',
            '&:hover': {
              backgroundColor: (theme) => (theme.palette.mode === 'light' ? '#212121' : '#FFF'),
            },
          }}
        >
          {String(t('common.signOut'))}
        </Button>
      </DialogActions>
    </Dialog>
  );
}
